(() => {
  "use strict";

  const PDF_FILE_NAME = "GBT2828.1-2003_抽样检验用表及使用教程_正式整理版.pdf";
  const PDF_BASE64 = [
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    "",
    ""
  ].join("");

  const decodePdf = () => {
    const binary = atob(PDF_BASE64);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) {
      bytes[index] = binary.charCodeAt(index);
    }
    return new Blob([bytes], { type: "application/pdf" });
  };

  const initialiseReference = () => {
    const preview = document.getElementById("gbt2828PdfPreview");
    const openLink = document.getElementById("gbt2828PdfOpen");
    const downloadLink = document.getElementById("gbt2828PdfDownload");
    const status = document.getElementById("gbt2828PdfStatus");

    if (!preview || !openLink || !downloadLink) return;

    try {
      const pdfUrl = URL.createObjectURL(decodePdf());
      preview.src = pdfUrl + "#page=1&zoom=page-width";
      openLink.href = pdfUrl;
      downloadLink.href = pdfUrl;
      downloadLink.download = PDF_FILE_NAME;
      openLink.removeAttribute("aria-disabled");
      downloadLink.removeAttribute("aria-disabled");
      if (status) status.textContent = "高清矢量版已加载，可在预览器中缩放、翻页或全屏查看。";
      window.addEventListener("beforeunload", () => URL.revokeObjectURL(pdfUrl), { once: true });
    } catch (error) {
      if (status) status.textContent = "当前浏览器未能载入内嵌预览，请更换现代浏览器后重试。";
    }
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initialiseReference, { once: true });
  } else {
    initialiseReference();
  }
})();
